<?php $page_title='Admin Dashboard'; require 'layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='admin_food'){try{$title=trim($_POST['title']);$qty=(int)$_POST['quantity'];$loc=trim($_POST['location']);$exp=$_POST['expiry_date'];$image=upload_image('food_image','foods','admin_food_');if(!$title||$qty<1||!$loc||!$exp||!$image)throw new RuntimeException('Title, quantity, location, expiry and a real food image are required.');$pdo->prepare("INSERT INTO food_donations(donor_id,title,category,description,quantity,unit,location,expiry_date,image,status) VALUES(?,?,?,?,?,?,?,?,?,'available')")->execute([user()['id'],$title,trim($_POST['category']??'Other'),trim($_POST['description']??''),$qty,trim($_POST['unit']??'servings'),$loc,$exp,$image]);flash('success','Food donation published.');}catch(Throwable $e){flash('error',$e->getMessage());}}redirect('index.php');}
$stats=$pdo->query("SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM food_donations) donations,(SELECT COUNT(*) FROM food_donations WHERE status='available') available,(SELECT COUNT(*) FROM food_requests) requests,(SELECT COUNT(*) FROM ngos) ngos,(SELECT COUNT(*) FROM volunteers) volunteers,(SELECT COUNT(*) FROM campaigns) campaigns,(SELECT COUNT(*) FROM deliveries WHERE status='delivered') deliveries,(SELECT COUNT(*) FROM reports WHERE status IN ('open','reviewing')) reports,(SELECT COUNT(*) FROM community_posts) posts")->fetch();
$recent=$pdo->query("SELECT f.title,f.quantity,f.unit,f.status,f.created_at,u.name donor FROM food_donations f JOIN users u ON u.id=f.donor_id ORDER BY f.created_at DESC LIMIT 6")->fetchAll();
$admin_cards=[['Users','users.php','👥','Manage accounts, roles and profiles',intval($stats['users'])],['Food Listings','foods.php','🍱','Review availability and food photos',intval($stats['donations'])],['NGOs','ngos.php','🏢','Verify organizations and foundations',intval($stats['ngos'])],['Volunteers','volunteers.php','🤝','Manage availability and verification',intval($stats['volunteers'])],['Donations','donations.php','🎁','Track every food contribution',intval($stats['donations'])],['Deliveries','deliveries.php','🚚','Monitor pickup and delivery status',intval($stats['deliveries'])],['Campaigns','campaigns.php','📣','Create food rescue campaigns',intval($stats['campaigns'])],['Community','community.php','💬','Moderate posts and meetings',intval($stats['posts'])],['Reports','reports.php','🚩','Review complaints and safety reports',intval($stats['reports'])],['Analytics','analytics.php','📈','View platform impact metrics',intval($stats['completed']??0)]];
